        uv                    = frac(uv) * instance.uv.xy + instance.uv.zw;
        aoUV                  = instance.world._m21 > .5 ? frac(input.uv1) * instance.uv.xy + instance.uv.zw : uv;
        baseFactor            = instance.baseColor;
        matFactor             = instance.material;
