  : SV_Target
{
    float4 previous = mul(previousViewProjection, float4(input.direction, 0));
    float2 uv       = previous.xy / max(previous.w, .00001) * float2(.5, -.5) + .5;
    return float4(uv - input.uv, irradiance[1].w > .5 ? 0 : 1, irradiance[1].w > .5 ? 0 : 1);
}

